public List<SkillType> GenerateSkills()
	{
		List<SkillType> list = new List<SkillType>();
		if (DefaultPrimarySkill != SkillType.None)
		{
			list.Add(DefaultPrimarySkill);
		}
		if (DefaultSecondarySkills.Any())
		{
			list.AddRange(DefaultSecondarySkills);
		}
		if (DefaultActiveSkills.Any())
		{
			list.AddRange(DefaultActiveSkills);
		}
		return (from s in list.Distinct()
			select (s)).ToList();
	}

