public List<IAdventurerTalent> GenerateTalents()
	{
		List<IAdventurerTalent> list = new List<IAdventurerTalent>();
		list.Add(new HitRateEnhancementTalent());
		list.Add(new NegativeEffectEnhancementTalent());
		list.Add(new ElementDamageEnhancementTalent());
		if (OutputType == OutputType.Fire)
		{
			list.Add(new FireShieldTalent());
		}
		if (OutputType == OutputType.Poison)
		{
			list.Add(new PoisonEnhancementTalent());
		}
		if (OutputType == OutputType.Physical)
		{
			list.Add(new PhysicalEnhancementTalent());
		}
		if (OutputType == OutputType.Shadow)
		{
			list.Add(new ShadowEffectEnhancementTalent());
		}
		if (OutputType == OutputType.Ice)
		{
			list.Add(new IceEnhancementTalent());
		}
		if (OutputType == OutputType.Divine)
		{
			list.Add(new DivineEnhancementTalent());
		}
		if (OutputType == OutputType.Lightening)
		{
			list.Add(new LightningShieldTalent());
		}
		if (CorrespondingClassStyle == UnitClassStyle.SpellKiller || CorrespondingClassStyle == UnitClassStyle.PhysicalKiller)
		{
			list.AddRange(new List<IAdventurerTalent>
			{
				new DodgeEnhancementTalent(),
				new EnhancedEffectMasteryTalent(),
				new EnhancedResistancesTalent(),
				new CritDamageBoostTalent(),
				new EfficiencyTalent(),
				new StunEnhancementTalent(),
				new ShadowOfGhostTalent()
			});
		}
		if (CorrespondingClassStyle == UnitClassStyle.SpellWarrior || CorrespondingClassStyle == UnitClassStyle.PhysicalWarrior)
		{
			list.AddRange(new List<IAdventurerTalent>
			{
				new VitalityEnhancementTalent(),
				new TauntEnhancementTalent(),
				new EnhancedEffectMasteryTalent(),
				new EnhancedResistancesTalent(),
				new EfficiencyTalent(),
				new StunEnhancementTalent(),
				new RestrictionOfTimeTalent()
			});
		}
		if (CorrespondingClassStyle == UnitClassStyle.PhysicalDefender || CorrespondingClassStyle == UnitClassStyle.SpellDefender || CorrespondingClassStyle == UnitClassStyle.Protector)
		{
			list.AddRange(new List<IAdventurerTalent>
			{
				new VitalityEnhancementTalent(),
				new TauntEnhancementTalent(),
				new FurySpeedTalent(),
				new EnhancedEffectMasteryTalent(),
				new EnhancedResistancesTalent(),
				new RecoveryEnhancementTalent(),
				new ProtectorTalent()
			});
		}
		if (CorrespondingClassStyle == UnitClassStyle.PhysicalSupporter || CorrespondingClassStyle == UnitClassStyle.SpellSupporter)
		{
			list.AddRange(new List<IAdventurerTalent>
			{
				new DodgeEnhancementTalent(),
				new FurySpeedTalent(),
				new EnhancedEffectMasteryTalent(),
				new EnhancedResistancesTalent(),
				new EfficiencyTalent(),
				new RecoveryEnhancementTalent(),
				new BlackBloodTalent()
			});
		}
		if (CorrespondingClassStyle == UnitClassStyle.Healer)
		{
			list.AddRange(new List<IAdventurerTalent>
			{
				new DodgeEnhancementTalent(),
				new FurySpeedTalent(),
				new EnhancedEffectMasteryTalent(),
				new EnhancedResistancesTalent(),
				new EfficiencyTalent(),
				new RecoveryEnhancementTalent(),
				new DivineHeartTalent()
			});
		}
		list.AddRange(GenerateSkills().Select(SkillExtensions.GetSkillLogic).SelectMany((SkillLogicBase s) => s.CreateSkillTalents()));
		return list;
	}

