public AttributeBuff GetBuff()
	{
		AttributeBuff attributeBuff;
		if (SlotNumber == 2)
		{
			attributeBuff = new AttributeBuff();
			attributeBuff.AttributeType = AttributeType.Agility;
			attributeBuff.ModificationType = ModificationType.Multiplication;
			attributeBuff.Value = 0.08;
			attributeBuff.Seconds = 1;
			return attributeBuff;
		}
		attributeBuff = new AttributeBuff();
		attributeBuff.AttributeType = AttributeType.CritDamage;
		attributeBuff.ModificationType = ModificationType.Addition;
		attributeBuff.Value = 0.15;
		attributeBuff.Seconds = 1;
		return attributeBuff;
	}

protected override List<ISpecialEffectDataLoad> GetEffects(AdventurerProfile profile)
	{
		AttributeBuff buff = GetBuff();
		List<ISpecialEffectDataLoad> list = new List<ISpecialEffectDataLoad>();
		list.Add(new ArmorOfWindAttributeEnhancementData
		{
			IsStar = false,
			ModificationType = buff.ModificationType,
			Value = buff.Value,
			Type = buff.AttributeType
		});
		return list;
	}

