public AttributeBuff GetBuff()
	{
		if (SkillType == SkillType.CurseOfTheDead)
		{
			if (SlotNumber == 2)
			{
				AttributeBuff attributeBuff = new AttributeBuff();
				attributeBuff.AttributeType = AttributeType.DodgeRateAdjustment;
				attributeBuff.ModificationType = ModificationType.Addition;
				attributeBuff.Value = 0.1;
				attributeBuff.Seconds = 5;
				return attributeBuff;
			}
			if (SlotNumber == 3)
			{
				AttributeBuff attributeBuff = new AttributeBuff();
				attributeBuff.AttributeType = AttributeType.HitRateAdjustment;
				attributeBuff.ModificationType = ModificationType.Addition;
				attributeBuff.Value = 0.1;
				attributeBuff.Seconds = 5;
				return attributeBuff;
			}
		}
		if (SkillType == SkillType.GhostlySmoke)
		{
			if (SlotNumber == 2)
			{
