public static bool IsAvaliable(this IAdventurerTalent talent, AdventurerProfile profile)
	{
		return talent.GetTier() switch
		{
			AdventurerTalentTier.First => profile.Talents.Where((IAdventurerTalent t) => t.GetTier() == AdventurerTalentTier.First).Sum((IAdventurerTalent t) => t.GetCurrentLevel()) < 10, 
			AdventurerTalentTier.Second => profile.Talents.Where((IAdventurerTalent t) => t.GetTier() == AdventurerTalentTier.First).Sum((IAdventurerTalent t) => t.GetCurrentLevel()) >= 10 && profile.Talents.Where((IAdventurerTalent t) => t.GetTier() == AdventurerTalentTier.Second).Sum((IAdventurerTalent t) => t.GetCurrentLevel()) == 0, 
			AdventurerTalentTier.Third => profile.Talents.Where((IAdventurerTalent t) => t.GetTier() == AdventurerTalentTier.Second).Sum((IAdventurerTalent t) => t.GetCurrentLevel()) >= 1 && profile.Talents.Where((IAdventurerTalent t) => t.GetTier() == AdventurerTalentTier.Third).Sum((IAdventurerTalent t) => t.GetCurrentLevel()) < 5, 
			AdventurerTalentTier.Forth => profile.Talents.Where((IAdventurerTalent t) => t.GetTier() == AdventurerTalentTier.Third).Sum((IAdventurerTalent t) => t.GetCurrentLevel()) >= 5 && profile.Talents.Where((IAdventurerTalent t) => t.GetTier() == AdventurerTalentTier.Forth).Sum((IAdventurerTalent t) => t.GetCurrentLevel()) < 1, 
			_ => false, 
		};
	}

public static int GetTalentCostPerLevel(this IAdventurerTalent talent)
	{
		switch (talent.GetTier())
		{
		case AdventurerTalentTier.First:
		case AdventurerTalentTier.Third:
			return 1;
		case AdventurerTalentTier.Second:
			return 1;
		default:
			return 1;
		}
	}

public static bool CostMet(this IAdventurerTalent talent, AdventurerProfile profile)
	{
		return profile.TalentPoints >= talent.GetTalentCostPerLevel();
	}

public static void Upgrade(this IAdventurerTalent talent, AdventurerProfile profile)
	{
		if (talent.IsAvaliable(profile) && talent.CostMet(profile) && talent.GetCurrentLevel() < talent.GetMaxLevel())
		{
			profile.TalentPoints -= talent.GetTalentCostPerLevel();
			talent.UpgradeLogic(profile);
		}
	}

public static void Downgrade(this IAdventurerTalent talent, AdventurerProfile profile)
	{
		if (talent.GetCurrentLevel() > 0)
		{
			profile.TalentPoints += talent.GetTalentCostPerLevel();
			talent.DowngradeLogic(profile);
		}
	}

public static void Reset(this IAdventurerTalent talent, AdventurerProfile profile)
	{
		if (talent.GetCurrentLevel() > 0)
		{
			profile.TalentPoints += talent.GetTalentCostPerLevel() * talent.GetCurrentLevel();
			talent.ResetLogic(profile);
		}
	}

public static double GetMainSkillDamageBoostRate(this IBattleEffectSource effectSource)
	{
		if (effectSource is AdventureUnitSkill)
		{
			AdventureUnitSkill adventureUnitSkill = effectSource as AdventureUnitSkill;
			if (adventureUnitSkill.Skill.CommandType == SkillCommandType.Main && adventureUnitSkill.GetActiveTalents().OfType<ElementalDamageIncreaseTalent>().Any())
			{
				return adventureUnitSkill.GetActiveTalents().OfType<ElementalDamageIncreaseTalent>().Sum((ElementalDamageIncreaseTalent t) => t.GetRate());
			}
		}
		return 0.0;
	}

